5	import '../../../../core/resource.dart';
6	import '../../../entries/domain/entities/entry.dart';
7	import '../../../entries/domain/services/pending_entry_write_tracker.dart';
8	import '../../domain/repositories/dashboard_repository.dart';
9	
10	/// Drives `DashboardChartSection`'s own AI narrative paragraph (spec-8-2) —
11	/// a second, independent fetch from [DashboardCubit]'s own aggregate fetch
12	/// (Boundaries/Never: "couple the two `Resource`s into one state object"),
13	/// mirroring [DashboardCubit]'s exact shape: a DI `registerLazySingleton`,
14	/// constructor-subscribed to [PendingEntryWriteTracker.confirmedWrites] so
15	/// it recomputes on every entry write same as the aggregate, and [load] is
16	/// generation-guarded the same way.
17	///
18	/// Deliberately never caches a previous [load] result across calls, same
19	/// rationale [DashboardCubit] gives — every [load] re-emits
20	/// [ResourceLoading] first.
21	class DashboardNarrativeCubit extends Cubit<Resource<String>> {
22	  DashboardNarrativeCubit(this._repository, this._tracker)
23	    : super(const ResourceIdle()) {
24	    _confirmedSubscription = _tracker.confirmedWrites.listen((_) => load());
25	  }
26	
27	  final DashboardRepository _repository;
28	  final PendingEntryWriteTracker _tracker;
29	  late final StreamSubscription<({String tempId, Entry entry})>
30	  _confirmedSubscription;
31	
32	  /// Same generation-guard convention [DashboardCubit]'s own `_generation`
33	  /// uses — guards against a stale in-flight [load] call's result landing
34	  /// after a newer one has already superseded it.
35	  int _generation = 0;
36	
37	  /// Boundaries: "`queryParameters: {'period': 'all'}` — same fixed value
38	  /// as `dashboard-aggregate-get`" — [load]'s one and only call to
39	  /// [DashboardRepository.getNarrative] always passes this.
40	  Future<void> load() async {
41	    final generation = ++_generation;
42	    emit(ResourceLoading());
43	    final result = await _repository.getNarrative(period: 'all');
44	    // Mirrors `DashboardCubit.load()`'s own guard: `close()` can race this
45	    // awaited call, and a newer `load()` (constructor-triggered
46	    // `confirmedWrites` event, a second screen open, or a retry tap) can
47	    // have superseded this one while it was in flight.
48	    if (isClosed || generation != _generation) {
49	      return;
50	    }
51	    result.match(
52	      (failure) => emit(ResourceError(failure)),
53	      (text) => emit(ResourceData(text)),
54	    );
55	  }
56	
57	  @override
58	  Future<void> close() async {
59	    await _confirmedSubscription.cancel();
60	    return super.close();
61	  }
62	}
63

