26	/// A plain (non-mocktail) fake — same convention `dashboard_cubit_test.
27	/// dart`'s own `_FakeDashboardRepository` uses: several tests here need to
28	/// resolve two calls out of order (the stale-in-flight-call generation
29	/// guard), which a single static mocktail stub can't express as naturally.
30	/// [getAggregate] is never called by this cubit (`DashboardNarrativeCubit`
31	/// only ever calls [getNarrative]) — throws if reached.
32	class _FakeDashboardRepository implements DashboardRepository {
33	  final List<Either<Failure, String>> _results = [];
34	  final List<Completer<Either<Failure, String>>> _completers = [];
35	  final List<String> calls = [];
36	
37	  /// When `true`, [getNarrative] returns a `Completer`-backed future the
38	  /// test resolves explicitly (via [resolve]) rather than immediately
39	  /// returning a queued result.
40	  bool gated = false;
41	
42	  void queue(Either<Failure, String> result) {
43	    _results.add(result);
44	  }
45	
46	  void resolve(int callIndex, Either<Failure, String> result) {
47	    _completers[callIndex].complete(result);
48	  }
49	
50	  @override
51	  Future<Either<Failure, DashboardAggregate>> getAggregate({
52	    required String period,
53	  }) async => throw UnimplementedError('not expected to be called');
54	
55	  @override
56	  Future<Either<Failure, String>> getNarrative({required String period}) {
57	    calls.add(period);
58	    if (gated) {
59	      final completer = Completer<Either<Failure, String>>();
60	      _completers.add(completer);
61	      return completer.future;
62	    }
63	    if (_results.isEmpty) {
64	      throw StateError(
65	        'no queued getNarrative() result for call #${calls.length}',
66	      );
67	    }
68	    return Future.value(_results.removeAt(0));
69	  }
70	}
