178	/// Builds a fresh [_FakeAccountSettingsRepository] + [AccountSettingsCubit]
179	/// pair and pumps the real screen around it, registering both for cleanup.
180	///
181	/// Deliberately constructed *inside* each `testWidgets` body (via this
182	/// helper) rather than in a shared `setUp()` — `setUp()`'s callback runs in
183	/// `package:test`'s own per-test zone, a different zone than the one
184	/// `TestWidgetsFlutterBinding` establishes for the `testWidgets` callback
185	/// itself. A `StreamSubscription` (here, `AccountSettingsCubit`'s own
186	/// subscription to the repository's stream, set up in its constructor)
187	/// created in that outer zone does not reliably get its pending events
188	/// flushed by `tester.pump()`'s zone-scoped microtask draining — observed
189	/// directly: `cubit.state` updated correctly, but the `BlocBuilder`-driven
190	/// widget never rebuilt, no matter how many `pump()` calls followed.
191	/// Constructing the cubit here, inside the same zone `tester.pump()`
192	/// drains, avoids the mismatch entirely.
193	Future<(_FakeAccountSettingsRepository, AccountSettingsCubit)> _pumpScreen(
194	  WidgetTester tester,
195	) async {
196	  final fakeRepository = _FakeAccountSettingsRepository();
197	  final cubit = AccountSettingsCubit(fakeRepository);
198	  addTearDown(() => cubit.close());
199	  addTearDown(fakeRepository.dispose);
200	
201	  final router = _routerWith(
202	    AccountSettingsScreen(
203	      cubit: cubit,
204	      dashboardCubit: _buildDashboardCubit(),
205	      narrativeCubit: _buildNarrativeCubit(),
206	    ),
207	  );
208	  addTearDown(router.dispose);
209	  await tester.pumpWidget(MaterialApp.router(routerConfig: router));
210	
211	  return (fakeRepository, cubit);
212	}
